package music.resonance.mobile;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class LibraryUnderstandingTest {
    private JSONObject song(String id){return Json.object("id",id,"title","Night","artist","Aster","duration",180,"available",true);}
    @Test public void genreEditDoesNotFreezeFeaturedArtists(){JSONObject t=song("a");Json.put(t,"title","Night feat. Nova (Official Video)");MetadataEdits.apply(t,Json.object("genre","Rock"));ArtistCredits.repair(t);assertEquals(List.of("Aster","Nova"),ArtistCredits.names(t));assertFalse(MetadataEdits.locked(t,"artist"));assertTrue(MetadataEdits.locked(t,"genre"));}
    @Test public void explicitArtistsPreserveBandNamesAndInvalidateOldIdentity(){JSONObject t=song("a");Json.put(t,"genre","Rock");Json.put(t,"metadataUrl","old");MetadataEdits.apply(t,Json.object("artist","Peter, Paul and Mary; Nova","artistCredits",new JSONArray().put("Peter, Paul and Mary").put("Nova")));ArtistCredits.repair(t);assertEquals(List.of("Peter, Paul and Mary","Nova"),ArtistCredits.names(t));assertTrue(t.optBoolean("genreIdentityStale"));assertEquals("",t.optString("metadataUrl"));}
    @Test public void legacyChoicesRemainProtectedWhenEditingAnotherField(){JSONObject t=song("a");Json.put(t,"metadataStatus","manual");MetadataEdits.apply(t,Json.object("album","New"));assertTrue(MetadataEdits.locked(t,"artist"));assertTrue(MetadataEdits.locked(t,"genre"));}
    @Test public void confirmingExistingGenreIsAnExplicitProtectedChoice(){JSONObject t=song("a");Json.put(t,"genre","Rock");Json.put(t,"genreBasis","artist");MetadataEdits.apply(t,Json.object("genre","Rock","confirmFields",new JSONArray().put("genre")));assertTrue(t.optBoolean("genreLocked"));assertEquals("manual",t.optString("genreBasis"));assertFalse(MetadataEdits.locked(t,"artist"));assertTrue(MetadataEdits.snapshot(t).has("genreEvidence"));}
    @Test public void sameRecordingCanReuseGenreButVersionsAndEstimatesCannot(){JSONObject original=song("a"),copy=song("b"),remix=song("c"),other=song("d");Json.put(original,"genre","Rock");Json.put(remix,"title","Night (Nova Remix)");Json.put(other,"artist","Other");GenreResearch research=new GenreResearch(url->new JSONObject(),Json.object("rock","Rock"));research.seed(new JSONArray().put(original).put(copy).put(remix).put(other));assertEquals("Rock",copy.optString("genre"));assertEquals("local-recording",copy.optJSONArray("genreEvidence").optJSONObject(0).optString("scope"));assertEquals("",remix.optString("genre"));assertEquals("",other.optString("genre"));JSONObject target=song("e");research.seed(new JSONArray().put(copy).put(target));assertEquals("",target.optString("genre"));}
    @Test public void conflictingLocalLabelsDoNotProduceAFalseAnswer(){JSONObject a=song("a"),b=song("b"),c=song("c");Json.put(a,"genre","Rock");Json.put(b,"genre","Jazz");new GenreResearch(url->new JSONObject(),new JSONObject()).seed(new JSONArray().put(a).put(b).put(c));assertEquals("",c.optString("genre"));}
    @Test public void titleWordsAreNotFeaturedCredits(){assertEquals("A featured performer",GenreResearch.title(Json.object("title","A featured performer")));assertEquals("My song (Featured edition)",GenreResearch.title(Json.object("title","My song (Featured edition)")));assertEquals("Night",GenreResearch.title(Json.object("title","Night feat. Nova")));}
    @Test public void strongerEvidenceIsPersistedEvenWhenTheGenreTextIsUnchanged(){JSONObject original=song("a"),copy=song("b");Json.put(original,"genre","Rock");Json.put(copy,"genre","Rock");Json.put(copy,"genreBasis","artist");JSONArray changed=new GenreResearch(url->new JSONObject(),new JSONObject()).seed(new JSONArray().put(original).put(copy));assertEquals(1,changed.length());assertEquals("track",changed.optJSONObject(0).optString("genreBasis"));}
}
